const token = $('Store Token').item.json.accessToken;
const apiBase = $('Store Token').item.json.apiBase;
const slugPayload = $('Get Existing Slugs').item.json;
const slugList = slugPayload?.data || slugPayload || [];

const normalizeSlug = (value) => String(value || '')
  .normalize('NFKC')
  .replace(/[\u200c\u200d\u200e\u200f\ufeff]/g, '')
  .toLowerCase()
  .trim()
  .replace(/\s+/g, '-')
  .replace(/[^\u0600-\u06FFa-z0-9-]/gi, '')
  .replace(/-+/g, '-')
  .replace(/^-|-$/g, '');

const normalizeText = (value) => String(value || '')
  .normalize('NFKC')
  .replace(/[\u200c\u200d\u200e\u200f\ufeff]/g, '')
  .toLowerCase()
  .replace(/[^\u0600-\u06FFa-z0-9\s]/gi, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const parseKeywordList = (raw) => {
  if (Array.isArray(raw)) return raw.map(String).map((s) => s.trim()).filter(Boolean);
  if (raw == null || raw === '') return [];
  if (typeof raw === 'string') {
    try {
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) return parsed.map(String).map((s) => s.trim()).filter(Boolean);
    } catch (e) {
      return raw.split(/[\n,]+/).map((s) => s.trim()).filter(Boolean);
    }
  }
  return [];
};

const existingSlugs = new Set(
  (Array.isArray(slugList) ? slugList : [])
    .map((x) => normalizeSlug(typeof x === 'string' ? x : (x?.slug || '')))
    .filter(Boolean)
);

const coveredTitles = [];
const coveredPhrases = new Set();
const STOP = new Set(['راهنمای','خرید','نگهداری','شستشوی','برای','با','از','و','در','به','یک','این','آن','مدل','ترین','های','ها']);

const addCovered = (value) => {
  const t = normalizeText(value);
  if (!t) return;
  coveredPhrases.add(t);
  coveredTitles.push(t);
  for (const part of t.split(' ')) {
    if (part.length >= 4) coveredPhrases.add(part);
  }
};

for (const x of (Array.isArray(slugList) ? slugList : [])) {
  addCovered(typeof x === 'string' ? x : x?.slug);
}

const authHeaders = { Authorization: `Bearer ${token}` };
const safeGet = async (path, qs) => {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET', url: `${apiBase}${path}`, qs: qs || {}, headers: authHeaders, json: true,
    });
    return res?.data ?? res;
  } catch (e) {
    return null;
  }
};

const [categoriesPayload, productsPayload, blogsPayload, snapshot] = await Promise.all([
  safeGet('/Categories', { isShowInLanding: true, pageSize: 50, onlyActives: true }),
  safeGet('/Products', { onlyActives: true, pageSize: 50 }),
  safeGet('/Blogs', { onlyActives: false, pageSize: 100 }),
  safeGet('/SeoOps/snapshot', { staleDays: 90, take: 20 }),
]);

const categories = categoriesPayload?.records || (Array.isArray(categoriesPayload) ? categoriesPayload : []);
const products = productsPayload?.records || (Array.isArray(productsPayload) ? productsPayload : []);
const blogs = blogsPayload?.records || (Array.isArray(blogsPayload) ? blogsPayload : []);
for (const b of blogs) {
  addCovered(b.titleFa); addCovered(b.slug); addCovered(b.metaKeywordsFa); addCovered(b.excerptFa);
}

const isCovered = (keyword) => {
  const t = normalizeText(keyword);
  if (!t) return true;
  if (coveredPhrases.has(t)) return true;
  const slug = normalizeSlug(keyword);
  if (slug && existingSlugs.has(slug)) return true;
  for (const title of coveredTitles) {
    if (title.includes(t) || t.includes(title)) return true;
    const core = t.split(' ').filter((w) => w.length >= 3 && !STOP.has(w));
    const titleCore = title.split(' ').filter((w) => w.length >= 3 && !STOP.has(w));
    if (core.length && titleCore.length) {
      const hit = core.filter((w) => titleCore.includes(w)).length;
      if (hit / Math.max(core.length, 1) >= 0.6) return true;
    }
  }
  return false;
};

const daySeed = Math.floor(Date.now() / 86400000);
const envKeywords = parseKeywordList($env.BLOG_KEYWORDS_JSON || $env.SEED_TOPICS_JSON || '');
const catalogNames = [
  ...categories.map((c) => c.persianName).filter(Boolean),
  ...products.map((p) => p.name).filter(Boolean),
];

const prefixes = ['خرید', 'قیمت', 'بهترین', 'راهنمای خرید'];
const seedSet = new Set();
const addSeed = (s) => {
  const t = String(s || '').trim();
  if (t.length >= 4) seedSet.add(t);
};
for (const name of catalogNames) {
  addSeed(name);
  for (const p of prefixes) addSeed(`${p} ${name}`);
}
for (const k of envKeywords) addSeed(k);
addSeed($env.BLOG_SUGGEST_QUERY || 'لوپ دندان‌پزشکی');
addSeed('لوپ پریزماتیک');
addSeed('لوپ گالیله‌ای');
addSeed('هدلایت LED دندان‌پزشکی');

const allSeeds = [...seedSet];
const seedCount = Math.min(10, allSeeds.length || 1);
const seeds = [];
for (let i = 0; i < seedCount; i++) {
  seeds.push(allSeeds[(daySeed + i * 3) % allSeeds.length]);
}

const fetchSuggest = async (q) => {
  try {
    const suggest = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://suggestqueries.google.com/complete/search',
      qs: { client: 'chrome', hl: 'fa', q },
      headers: { 'User-Agent': 'Mozilla/5.0' },
      json: true,
    });
    const arr = Array.isArray(suggest?.[1]) ? suggest[1] : [];
    return arr.map((item) => {
      if (typeof item === 'string') return item;
      if (Array.isArray(item)) return String(item[0] || '');
      return String(item || '');
    }).filter(Boolean);
  } catch (e) {
    return [];
  }
};

const suggestResults = await Promise.all(seeds.map((s) => fetchSuggest(s)));
const demandQueries = [];
const seenDemand = new Set();
seeds.forEach((seed, idx) => {
  for (const q of (suggestResults[idx] || []).slice(0, 10)) {
    const key = normalizeText(q);
    if (!key || seenDemand.has(key)) continue;
    seenDemand.add(key);
    demandQueries.push({ query: q, seed });
  }
});

const COMMERCIAL = ['خرید', 'قیمت', 'بهترین', 'ارزان', 'آنلاین', 'فروش', 'دیجی', 'راهنما', 'نگهداری', 'شستشو'];
const scoreDemand = (query) => {
  const t = normalizeText(query);
  let score = 50;
  const words = t.split(' ').filter(Boolean);
  if (words.length >= 3) score += 12;
  if (words.length >= 4) score += 6;
  for (const c of COMMERCIAL) if (t.includes(c)) score += 8;
  for (const name of catalogNames) {
    const n = normalizeText(name);
    if (n && t.includes(n)) { score += 15; break; }
  }
  if (/(لوپ|هدلایت|دندان|پریزماتیک|گالیله|بزرگ‌نمایی|لنز|فریم)/.test(t)) score += 10;
  if (/(دیجی\s*کالا|ترب|آمازون)/.test(t)) score -= 8;
  return score;
};

const candidates = [];
const pushCandidate = (keyword, meta) => {
  const k = String(keyword || '').trim();
  if (k.length < 6 || k.length > 80) return;
  if (isCovered(k)) return;
  const slug = normalizeSlug(k);
  if (!slug || existingSlugs.has(slug)) return;
  candidates.push({
    keyword: k,
    slug,
    source: meta.source,
    intent: meta.intent,
    score: meta.score,
    seed: meta.seed || null,
    brief: meta.brief || '',
    relatedCategory: meta.relatedCategory || null,
    relatedProduct: meta.relatedProduct || null,
  });
};

for (const d of demandQueries) {
  pushCandidate(d.query, {
    source: 'search-demand',
    intent: 'autocomplete',
    score: scoreDemand(d.query),
    seed: d.seed,
    brief: `عبارت واقعی پیشنهادی گوگل از seed «${d.seed}» (proxy تقاضای جستجو).`,
  });
}

if (candidates.filter((c) => c.source === 'search-demand').length < 5) {
  for (const c of categories) {
    const name = c.persianName || '';
    if (!name) continue;
    pushCandidate(`راهنمای خرید ${name}`, {
      source: 'category-gap-fallback', intent: 'buying-guide', score: 28,
      relatedCategory: { id: c.id, name, slug: c.slug },
      brief: `Fallback شکاف دسته «${name}».`,
    });
  }
}

candidates.sort((a, b) => b.score - a.score || a.keyword.localeCompare(b.keyword, 'fa'));
const demandOnly = candidates.filter((c) => c.source === 'search-demand');
const pool = (demandOnly.length >= 3 ? demandOnly : candidates).slice(0, 12);

let pick = null;
if (pool.length) {
  pick = pool[daySeed % pool.length];
} else {
  const fallback = envKeywords[0] || catalogNames[0] || 'لوپ دندان‌پزشکی';
  let slug = normalizeSlug(`${fallback}-${daySeed}`) || `blog-${daySeed}`;
  let i = 2;
  while (existingSlugs.has(slug) && i < 30) slug = `${normalizeSlug(fallback)}-${daySeed}-${i++}`;
  pick = {
    keyword: fallback, slug, source: 'fallback-unique', intent: 'fallback', score: 1,
    brief: 'fallback یکتا', relatedCategory: null, relatedProduct: null, seed: null,
  };
}

return [{
  json: {
    token,
    apiBase,
    selectedKeyword: pick.keyword,
    selectedTopic: pick.keyword,
    slug: pick.slug,
    intent: pick.intent,
    topicSource: pick.source,
    contentBrief: pick.brief,
    suggestSeed: pick.seed,
    relatedCategory: pick.relatedCategory,
    relatedProduct: pick.relatedProduct,
    seedsUsed: seeds,
    demandQueryCount: demandQueries.length,
    candidateCount: candidates.length,
    topCandidates: pool.slice(0, 8).map((c) => ({ keyword: c.keyword, score: c.score, source: c.source })),
    seoHint: snapshot ? `blogs=${snapshot.activeBlogs}/${snapshot.inactiveBlogs}` : 'snapshot-unavailable',
    catalogStats: { categories: categories.length, products: products.length, blogs: blogs.length },
    existingSlugCount: existingSlugs.size,
    existingSlugs: [...existingSlugs],
  },
}];

const raw = $input.first().json; // newest 'Generate Article (LLM)' answer (direct parent)
let content = String(raw.choices?.[0]?.message?.content || '').trim();
if (!content) throw new Error('LLM returned empty content');
content = content.replace(/<\/?div[^>]*>/gi, ' ').trim();
const fence = content.match(/```(?:json)?\s*([\s\S]*?)```/i);
if (fence) content = fence[1].trim();
const extractJsonObject = (text) => {
  const start = text.indexOf('{');
  if (start < 0) throw new Error('LLM did not return valid JSON');
  let depth = 0, inStr = false, esc = false;
  for (let i = start; i < text.length; i++) {
    const ch = text[i];
    if (inStr) {
      if (esc) { esc = false; continue; }
      if (ch === '\\') { esc = true; continue; }
      if (ch === '"') inStr = false;
      continue;
    }
    if (ch === '"') { inStr = true; continue; }
    if (ch === '{') depth++;
    else if (ch === '}') {
      depth--;
      if (depth === 0) return text.slice(start, i + 1);
    }
  }
  throw new Error('LLM did not return valid JSON');
};
let article;
try { article = JSON.parse(extractJsonObject(content)); } catch (e) { throw new Error('LLM did not return valid JSON'); }
const ctx = $('Discover & Select Topic').first().json;

const normalizeSlug = (value) => String(value || '')
  .normalize('NFKC')
  .replace(/[\u200c\u200d\u200e\u200f\ufeff]/g, '')
  .toLowerCase()
  .trim()
  .replace(/\s+/g, '-')
  .replace(/[^\u0600-\u06FFa-z0-9-]/gi, '')
  .replace(/-+/g, '-')
  .replace(/^-|-$/g, '');
const reserved = new Set(($('Discover & Select Topic').first().json.existingSlugs || []).map(normalizeSlug).filter(Boolean));
const lockSlug = (() => {
  const preferred = normalizeSlug(ctx.slug) || normalizeSlug(ctx.selectedKeyword) || 'blog-dental-loupes';
  if (!reserved.has(preferred)) return preferred;
  const day = new Date().toISOString().slice(0, 10).replace(/-/g, '');
  let c = preferred + '-' + day;
  if (!reserved.has(c)) return c;
  for (let i = 2; i <= 50; i++) {
    c = preferred + '-' + day + '-' + i;
    if (!reserved.has(c)) return c;
  }
  return preferred + '-' + Date.now();
})();

const keyword = ctx.selectedKeyword || 'لوپ دندان‌پزشکی';

const stripHtml = (s) => String(s || '').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/gi, ' ').replace(/\s+/g, ' ').trim();
const ensureMeta = (s, fallback) => {
  let t = String(s || fallback || '').trim();
  if (t.length < 70) {
    t = `${t} راهنمای کاربردی انتخاب، خرید و نگهداری ${keyword} برای دندان‌پزشکان.`.replace(/\s+/g, ' ').trim();
  }
  if (t.length > 160) t = t.slice(0, 157).trim() + '...';
  if (t.length < 70) t = (t + ' راهنمای کامل لوپ و تجهیزات دندان‌پزشکی برای خرید هوشمند.').slice(0, 160);
  return t;
};
const ensureContent = (html) => {
  let c = String(html || '').trim();
  if (!/href\s*=\s*["'][^"']*\/(products|categories|blog)\//i.test(c)) {
    c = `<p>برای دیدن گزینه‌های مرتبط، به <a href="/categories/">دسته‌بندی لوپ‌ها</a> سر بزنید.</p>` + c;
  }
  if (!/<h2[^>]*>\s*(سوالات متداول|پرسش‌های متداول|faq)/i.test(c)) {
    c += `<h2>سوالات متداول</h2>
<h3>${keyword} برای چه استفاده‌ای مناسب است؟</h3>
<p>بیشتر برای کارهای دقیق بالینی مانند ترمیمی، اندو و جراحی کاربرد دارد و اگر درست نگهداری شود وضوح تصویر خود را حفظ می‌کند.</p>
<h3>چطور ${keyword} را بشوییم؟</h3>
<p>شستشوی دستی با اسفنج نرم و شوینده ملایم معمولاً ایمن‌تر است؛ از ضربه‌های ناگهانی و شوک دمایی شدید پرهیز کنید.</p>
<h3>موقع خرید به چه نکاتی توجه کنیم؟</h3>
<p>بزرگ‌نمایی، میدان دید، فاصله کاری، وزن و سازگاری با هدلایت از مهم‌ترین معیارها هستند.</p>
<h3>آیا برای هدیه مناسب است؟</h3>
<p>بله، مخصوصاً اگر بسته‌بندی محکم و ظاهر شکیل داشته باشد و با سلیقه میزبان هماهنگ باشد.</p>
<h3>چطور براقیت آن حفظ شود؟</h3>
<p>بعد از شستشو با پارچه نرم خشک کنید و از اسکاچ زبر یا مواد بسیار اسیدی دوری کنید.</p>`;
  }
  let guard = 0;
  while (stripHtml(c).length < 520 && guard < 8) {
    c += `<p>در انتخاب ${keyword} بهتر است به نوع کار بالینی، فاصله کاری و راحتی استفاده در جلسات طولانی فکر کنید. مدل‌های ساده‌تر معمولاً همه‌کاره‌ترند و با سرویس‌های مختلف بهتر ست می‌شوند.</p>`;
    guard += 1;
  }
  return c;
};

const introFa = article.introFa || `اگر به دنبال ${keyword} هستید، این راهنما کمک می‌کند انتخاب کاربردی‌تری داشته باشید و بعد از خرید هم بهتر از آن نگهداری کنید.`;
const conclusionFa = article.conclusionFa || `در نهایت، ${keyword} وقتی ارزش خرید دارد که هم با فضای خانه هماهنگ باشد و هم نگهداری‌اش برای شما سخت نباشد.`;
const contentFa = ensureContent(article.contentFa);
const metaDescriptionFa = ensureMeta(article.metaDescriptionFa, introFa);
const excerptFa = ensureMeta(article.excerptFa || metaDescriptionFa, metaDescriptionFa).slice(0, 160);

const normalized = {
  ...article,
  titleFa: article.titleFa || keyword,
  introFa,
  contentFa,
  conclusionFa,
  excerptFa,
  metaDescriptionFa,
  metaKeywordsFa: article.metaKeywordsFa || `${keyword}, لوپ دندان‌پزشکی, هدلایت دندان‌پزشکی, خرید لوپ`,
  titleEn: article.titleEn || keyword,
  introEn: article.introEn || introFa,
  contentEn: ensureContent(article.contentEn || contentFa),
  conclusionEn: article.conclusionEn || conclusionFa,
  excerptEn: ensureMeta(article.excerptEn || article.metaDescriptionEn || excerptFa, excerptFa).slice(0, 160),
  metaDescriptionEn: ensureMeta(article.metaDescriptionEn || metaDescriptionFa, metaDescriptionFa),
  metaKeywordsEn: article.metaKeywordsEn || article.metaKeywordsFa || keyword,
  slug: lockSlug,
  primaryKeyword: keyword,
};

const hasKw = (s) => stripHtml(s).includes(keyword);
if (!hasKw(normalized.titleFa)) normalized.titleFa = keyword + " | " + normalized.titleFa;
if (!hasKw(normalized.introFa)) normalized.introFa = keyword + ": " + normalized.introFa;
if (!hasKw(normalized.contentFa)) {
  normalized.contentFa = "<p>موضوع این راهنما " + keyword + " است.</p>" + normalized.contentFa;
}
if (!hasKw(normalized.metaDescriptionFa)) {
  normalized.metaDescriptionFa = ensureMeta(keyword + ". " + normalized.metaDescriptionFa, normalized.introFa);
}
if (!hasKw(normalized.excerptFa)) {
  normalized.excerptFa = ensureMeta(keyword + ". " + normalized.excerptFa, normalized.metaDescriptionFa).slice(0, 160);
}

return [{
  json: {
    ...ctx,
    article: normalized,
  }
}];

// Ensure Unique Slug
// Runs right before "Quality Gates". Makes sure article.slug is not already used by a blog
// (checks GET /Blogs/getslugs?includeInactive=true + GET /Blogs/{slug}) and appends -2, -3, ...
// if it is. It is re-entered from "Slug Conflict?" (max 4 retries) when validate-content still
// reports "Slug '...' already exists."; retries use a date+random suffix.
const MAX_NUMERIC_SUFFIX = 50;
const MAX_SLUG_LEN = 200; // Blogs.Slug is varchar(200)

const ctx = $('Parse Article JSON').first().json;
const article = { ...(ctx.article || {}) };
const apiBase = ctx.apiBase;
const token = ctx.token;
const inJson = $input.first().json || {};
const isSlugRetry = !inJson.article && Array.isArray(inJson.data?.errors); // came from "Slug Conflict?"
const attempt = isSlugRetry ? Math.max(1, $runIndex) : 0; // 0 = first pass for this article
const headers = token ? { Authorization: `Bearer ${token}` } : {};

const normalizeSlug = (value) => String(value || '')
  .normalize('NFKC')
  .replace(/[\u200c\u200d\u200e\u200f\ufeff]/g, '')
  .toLowerCase()
  .trim()
  .replace(/\s+/g, '-')
  .replace(/[^\u0600-\u06FFa-z0-9-]/gi, '')
  .replace(/-+/g, '-')
  .replace(/^-|-$/g, '');
// Comparison key only (does not change the slug): fold Arabic yeh/kaf to Persian.
const key = (s) => normalizeSlug(s).replace(/[\u064A\u0649]/g, '\u06CC').replace(/\u0643/g, '\u06A9');

const today = new Date().toISOString().slice(0, 10).replace(/-/g, '');
let base = normalizeSlug(article.slug) || normalizeSlug(ctx.slug) || normalizeSlug(ctx.selectedKeyword) || `blog-${today}`;
base = base.slice(0, MAX_SLUG_LEN - 20).replace(/-+$/, '');

// 1) Known slugs: list from the start of the run + a fresh list from the backend.
const taken = new Set((ctx.existingSlugs || []).map(key).filter(Boolean));
try {
  const res = await this.helpers.httpRequest({
    method: 'GET',
    url: `${apiBase}/Blogs/getslugs`,
    qs: { includeInactive: true },
    headers,
    json: true,
  });
  const list = res?.data ?? res ?? [];
  for (const x of (Array.isArray(list) ? list : [])) {
    const k = key(typeof x === 'string' ? x : x?.slug);
    if (k) taken.add(k);
  }
} catch (e) { /* fall back to ctx.existingSlugs + per-slug check */ }

// 2) On a retry, also mark the slug that validate-content rejected.
const rejected = [];
if (attempt > 0) {
  const q = $input.first().json || {};
  if (q.data?.metrics?.slug) rejected.push(q.data.metrics.slug);
  for (const err of (q.data?.errors || q.errors || [])) {
    const m = String(err).match(/Slug\s+'([^']+)'/i);
    if (m) rejected.push(m[1]);
  }
  for (const r of rejected) taken.add(key(r));
}

// 3) Ask the backend directly for one slug (public endpoint; 200 + data:null when free).
const existsOnServer = async (slug) => {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: `${apiBase}/Blogs/${encodeURIComponent(slug)}`,
      headers,
      json: true,
    });
    return Boolean(res && res.isSuccess !== false && res.data);
  } catch (e) {
    const status = e?.httpCode ?? e?.response?.status ?? e?.statusCode;
    if (String(status) === '404') return false;
    return null; // unknown (network error) -> rely on the slug list
  }
};

const candidates = [];
if (attempt === 0) {
  candidates.push(base);
  for (let i = 2; i <= MAX_NUMERIC_SUFFIX; i++) candidates.push(`${base}-${i}`);
} else {
  for (let i = 0; i < 10; i++) {
    candidates.push(`${base}-${today}-${Math.random().toString(36).slice(2, 6)}`);
  }
}

const checked = [];
let chosen = null;
for (const c of candidates) {
  if (taken.has(key(c))) { checked.push({ slug: c, taken: 'list' }); continue; }
  const exists = await existsOnServer(c);
  checked.push({ slug: c, taken: exists === true ? 'server' : false });
  if (exists !== true) { chosen = c; break; }
}
if (!chosen) chosen = `${base}-${Date.now().toString(36)}`;

return [{
  json: {
    ...ctx,
    slug: chosen,
    article: { ...article, slug: chosen },
    slugCheck: { originalSlug: article.slug || null, base, chosen, attempt, rejected, checked: checked.slice(0, 10) },
  },
}];

// Collect Error for LLM
// Receives the error output of every node after "Generate Article (LLM)" (plus validation failures and
// a non-successful draft response) and builds feedback for the next LLM attempt.
// One run of this node == one failed LLM attempt, so $runIndex + 1 = failed attempts so far.
const MAX_ATTEMPTS = 3;      // total LLM attempts (initial + 2 retries)
const PREV_MAX = 6000;       // max chars of the previous LLM answer sent back

const j = $input.first()?.json || {};
let prev = '';
try { prev = String($prevNode?.name || ''); } catch (e) { prev = ''; }

// Count how many times the LLM node ran (robust second counter).
let llmRuns = 0;
for (let k = 0; k < 20; k++) {
  try { $('Generate Article (LLM)').all(0, k); llmRuns = k + 1; }
  catch (e) { if (/Run \d+ of node/.test(String(e?.message))) break; llmRuns = k + 1; }
}
const attempt = Math.max($runIndex + 1, llmRuns, 1);

const data = j.data && typeof j.data === 'object' ? j.data : {};
let failedNode = prev || 'unknown';
let kind = 'error';
let message = '';
const details = {};

const validationFrom = (d) => {
  const list = Array.isArray(d.errors) && d.errors.length ? d.errors.map(String) : [String(j.error || 'Quality gate failed')];
  message = list.join(' | ');
  details.errors = list;
  if (Array.isArray(d.warnings) && d.warnings.length) details.warnings = d.warnings.map(String);
  if (d.metrics) details.metrics = d.metrics;
};
const errorFrom = (e) => {
  if (typeof e === 'string') { message = e; return; }
  if (e && typeof e === 'object') {
    message = String(e.message || e.description || JSON.stringify(e));
    if (e.description && e.description !== e.message) details.description = String(e.description).slice(0, 1000);
    const status = e.httpCode ?? e.status ?? e.statusCode ?? e.context?.httpCode;
    if (status != null) details.httpStatus = String(status);
    return;
  }
  message = String(j.message || JSON.stringify(j).slice(0, 500));
};

if (prev === 'Draft Created?') {
  // POST /Blogs answered but isSuccess=false
  failedNode = 'Create Draft Blog';
  kind = 'api';
  message = String((typeof j.error === 'string' ? j.error : j.error?.message) || j.message || 'Backend did not confirm the draft (isSuccess=false)');
  details.response = JSON.stringify(j).slice(0, 1500);
} else if (prev === 'Slug Conflict?') {
  // validate-content returned isValid=false (not a pure slug conflict)
  failedNode = 'Quality Gates (validate-content)';
  kind = 'validation';
  validationFrom(data);
} else if (j.error) {
  // error output of a node (item json = input item + error)
  errorFrom(j.error);
  if (prev === 'Generate Article (LLM)') kind = 'llm_http';
  else if (prev === 'Parse Article JSON') kind = 'parse';
  else if (prev === 'Ensure Unique Slug') kind = 'code';
  else if (prev === 'Quality Gates' || prev === 'Create Draft Blog') kind = 'api';
} else if (data.isValid === false) {
  failedNode = 'Quality Gates (validate-content)';
  kind = 'validation';
  validationFrom(data);
} else {
  errorFrom(undefined);
}
message = (message || 'Unknown error').slice(0, 2000);

// Newest LLM answer (main output 0 of the latest run). Skipped when the LLM request itself failed.
let previousOutput = '', previousModel = '';
if (kind !== 'llm_http') {
  try {
    const r = $('Generate Article (LLM)').last(0)?.json || {};
    const m = r.choices?.[0]?.message || {};
    previousOutput = String(m.content || m.reasoning || '');
    previousModel = String(r.model || '');
  } catch (e) { /* no previous output */ }
}
if (previousOutput.length > PREV_MAX) {
  previousOutput = previousOutput.slice(0, 2000) + '\n…[truncated]…\n' + previousOutput.slice(-(PREV_MAX - 2000));
}

const topic = $('Discover & Select Topic').first().json;
const KEYS = 'titleFa, introFa, contentFa, conclusionFa, excerptFa, metaDescriptionFa, metaKeywordsFa, titleEn, introEn, contentEn, conclusionEn, excerptEn, metaDescriptionEn, metaKeywordsEn, slug';

let instruction = `پاسخ قبلی تو در مرحله «${failedNode}» خطا داد. مشکل را برطرف کن و دوباره بنویس.\n`
  + `Your previous answer failed at node "${failedNode}" with error:\n${message}\n`;
if (kind === 'validation') {
  instruction += `\nFix ALL of the content problems listed above. Rules: introFa at least 80 characters of text; `
    + `contentFa at least 500 characters of text, HTML with H2/H3, a FAQ section with the exact heading <h2>سوالات متداول</h2>, `
    + `and at least one internal link to /products/ or /categories/; conclusionFa at least 60 characters; `
    + `metaDescriptionFa between 70 and 160 characters; excerptFa at most 160 characters; metaKeywordsFa 3-12 comma-separated keywords.\n`;
} else if (kind === 'parse') {
  instruction += `\nYour answer could not be parsed as JSON (or required keys were missing).\n`;
} else if (kind === 'llm_http') {
  instruction += `\nThe previous request failed before an answer was produced (HTTP/provider error). Write the article now.\n`;
}
instruction += `\nReturn ONLY one valid JSON object (no markdown fences, no explanations, no text before or after) `
  + `with all required keys: ${KEYS}. The slug must be exactly: ${topic.slug || ''}. `
  + `Escape double quotes inside string values as \\" and do not put raw line breaks inside strings.`;

return [{
  json: {
    ...topic,
    llmFeedback: {
      attempt,
      maxAttempts: MAX_ATTEMPTS,
      failedNode,
      kind,
      error: message,
      details,
      previousModel,
      previousOutput,
      instruction,
      at: new Date().toISOString(),
    },
  },
}];
